#loginform {
 background: linear-gradient(135deg, #ffffff, #f7f9fc);
 padding: 35px 30px;
 border-radius: 18px;
 box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
 max-width: 420px;
 margin: auto;
 border: 1px solid rgba(0, 0, 0, 0.04);
}

/* ===== Labels ===== */
#loginform label {
 font-size: 14px;
 font-weight: 600;
 color: #2c2c2c;
 margin-bottom: 6px;
 display: block;
}

/* ===== Input Fields ===== */
#loginform input[type="text"],
#loginform input[type="password"] {
 width: 100%;
 padding: 14px 16px;
 border-radius: 14px;
 border: 1px solid #e4e8f0;
 background: #f9fbff;
 font-size: 15px;
 transition: all 0.35s ease;
 outline: none;
}

/* Focus Effect */
#loginform input:focus {
 border-color: #6a5acd;
 background: #ffffff;
 box-shadow: 0 0 0 4px rgba(106, 90, 205, 0.15);
}

/* ===== Remember Me ===== */
#loginform .forgetmenot {
 display: flex;
 align-items: center;
 margin-top: 12px;
}

#loginform .forgetmenot label {
 font-size: 13px;
 font-weight: 500;
 color: #555;
}

/* ===== Login Button ===== */
#loginform .button-primary {
 width: 100%;
 margin-top: 22px;
 padding: 14px;
 border-radius: 14px;
 border: none;
 background: linear-gradient(135deg, #6a5acd, #836fff);
 color: #ffffff;
 font-size: 16px;
 font-weight: 600;
 cursor: pointer;
 transition: all 0.35s ease;
 box-shadow: 0 12px 30px rgba(106, 90, 205, 0.35);
}

/* Button Hover */
#loginform .button-primary:hover {
 transform: translateY(-2px);
 box-shadow: 0 18px 40px rgba(106, 90, 205, 0.45);
 background: linear-gradient(135deg, #5a4bcf, #6f5dfb);
}

/* ===== Footer Links ===== */
#loginform p a {
 font-size: 13px;
 color: #6a5acd;
 font-weight: 600;
 text-decoration: none;
 transition: color 0.3s ease;
}

#loginform p a:hover {
 color: #483d8b;
 text-decoration: underline;
}

/* ===== Remove Default WP Styles ===== */
#loginform p {
 margin-bottom: 18px;
}

