 /* =========================================================
 EVER PEAK – Sticky Tabs (Light Blue, Full-width, Compact)
 matches screenshot + works with .is-active
 ========================================================= */

.ep-tabs{
 --bg1:#e9f6ff;
 --bg2:#d8f0ff;
 --pill:#ffffff;
 --pillLine:#cfe9ff;
 --text:#0b1b33;
 --muted:#5a6a80;
 --active1:#19a8ff;
 --active2:#0b79d0;
 --shadow:0 10px 22px rgba(2,20,46,.10);

 position: sticky;
 top: 0;
 z-index: 999;

 width: 100%;
 max-width: 1180px;
 margin: 0 auto 10px;

 /* make height small */
 padding: 5px 0;
 background: transparent;
 isolation:isolate;
}

/* Full width background bar */
.ep-tabs::before{
 content:"";
 position:absolute;
 left:50%;
 transform:translateX(-50%);
 top:0;
 width:100vw;
 height:100%;
 background: linear-gradient(180deg, var(--bg1), var(--bg2));
 border-bottom: 1px solid #cfe9ff;
 box-shadow: var(--shadow);
 backdrop-filter: blur(6px);
 -webkit-backdrop-filter: blur(6px);
 z-index:-1;
}

/* row */
.ep-tabs .ep-tabs-row{
 display:flex;
 gap:8px;
 align-items:center;
 overflow-x:auto;
 padding: 0 10px;
 scrollbar-width:none;
}
.ep-tabs .ep-tabs-row::-webkit-scrollbar{ display:none; }

/* tab link (compact height) */
.ep-tabs a{
 display:inline-flex;
 align-items:center;
 gap:7px;

 padding: 6px 10px; /* 👈 smaller height */
 border-radius: 999px;
 background: var(--pill);
 border:1px solid var(--pillLine);

 text-decoration:none;
 white-space:nowrap;

 font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
 font-size: 13px; /* 👈 slightly smaller */
 font-weight: 650;
 color: var(--muted);

 transition: background .18s ease, border-color .18s ease, color .18s ease, transform .18s ease, box-shadow .18s ease;
}

.ep-tabs a:hover{
 background:#f3faff;
 color: var(--text);
 border-color:#b9dcff;
 transform: translateY(-1px);
}

/* active tab (force win) */
.ep-tabs a.is-active{
 background: linear-gradient(180deg, var(--active1), var(--active2)) !important;
 color:#fff !important;
 border-color: var(--active2) !important;
 box-shadow: 0 8px 14px rgba(11,121,208,.22) !important;
 transform:none !important;
}

/* icon (smaller) */
.ep-tabs .ep-ic{
 width:18px;
 height:18px;
 display:inline-flex;
 align-items:center;
 justify-content:center;
 border-radius:50%;
 background:#eaf6ff;
 border:1px solid #cfe9ff;
 flex:0 0 18px;
}

.ep-tabs a.is-active .ep-ic{
 background: rgba(255,255,255,.25) !important;
 border-color: rgba(255,255,255,.35) !important;
}

.ep-tabs .ep-ic svg{
 width:12px;
 height:12px;
 fill:none;
 stroke: currentColor;
 stroke-width:2.2;
 stroke-linecap:round;
 stroke-linejoin:round;
}

/* section helper (optional) */
.ep-scroll-section{
 scroll-margin-top: 220px; /* adjust if needed */
}

/* mobile */
@media (max-width:640px){
 .ep-tabs{ padding:4px 0; margin-bottom:8px; }
 .ep-tabs a{ padding:6px 9px; font-size:12.5px; }
 .ep-tabs .ep-ic{ width:17px; height:17px; flex-basis:17px; }
}
 
 
</style>

<!-- Sticky Tabs -->
<nav class="ep-tabs" data-offset="110">
 <div class="ep-tabs-row">

 <a href="#ep-key-points" class="is-active">
 <span class="ep-ic" aria-hidden="true">
 <!-- Keypoints / list -->
 <svg viewBox="0 0 24 24"><path d="M8 6h13"/><path d="M8 12h13"/><path d="M8 18h13"/><path d="M3 6h.01"/><path d="M3 12h.01"/><path d="M3 18h.01"/></svg>
 </span>Key Points
 </a>

 <a href="#ep-trip-overview">
 <span class="ep-ic" aria-hidden="true">
 <!-- Overview / info -->
 <svg viewBox="0 0 24 24"><path d="M12 16v-5"/><path d="M12 8h.01"/><path d="M12 22a10 10 0 1 0-10-10 10 10 0 0 0 10 10Z"/></svg>
 </span>Trip Overview
 </a>

 <a href="#ep-highlights">
 <span class="ep-ic" aria-hidden="true">
 <!-- Highlights / spark -->
 <svg viewBox="0 0 24 24"><path d="M12 2l1.3 5.1L18 8.4l-4.1 3.2L15 17l-3-2.2L9 17l1.1-5.4L6 8.4l4.7-1.3Z"/></svg>
 </span>Highlights
 </a>

 <a href="#ep-itinerary">
 <span class="ep-ic" aria-hidden="true">
 <!-- Itinerary / route -->
 <svg viewBox="0 0 24 24"><path d="M6 6h12"/><path d="M6 12h8"/><path d="M6 18h10"/><path d="M18 12l3 3-3 3"/></svg>
 </span>Itinerary
 </a>

 <a href="#ep-include">
 <span class="ep-ic" aria-hidden="true">
 <!-- Include / check -->
 <svg viewBox="0 0 24 24"><path d="M9 12l2 2 4-5"/><path d="M12 22a10 10 0 1 0-10-10 10 10 0 0 0 10 10Z"/></svg>
 </span>Package Include
 </a>

 <a href="#ep-exclude">
 <span class="ep-ic" aria-hidden="true">
 <!-- Exclude / X -->
 <svg viewBox="0 0 24 24"><path d="M9 9l6 6"/><path d="M15 9l-6 6"/><path d="M12 22a10 10 0 1 0-10-10 10 10 0 0 0 10 10Z"/></svg>
 </span>Package Exclude
 </a>

 <a href="#ep-equipment">
 <span class="ep-ic" aria-hidden="true">
 <!-- Equipment / backpack -->
 <svg viewBox="0 0 24 24"><path d="M9 6a3 3 0 0 1 6 0"/><path d="M7 20h10"/><path d="M8 20V10a4 4 0 0 1 8 0v10"/><path d="M8 13h8"/></svg>
 </span>Equipment &amp; Gears
 </a>

 <a href="#ep-gallery">
 <span class="ep-ic" aria-hidden="true">
 <!-- Gallery / image -->
 <svg viewBox="0 0 24 24"><path d="M4 6h16v12H4z"/><path d="M8 10h.01"/><path d="M20 15l-5-5-6 6-2-2-3 3"/></svg>
 </span>Gallery
 </a>

 <a href="#ep-guide-map">
 <span class="ep-ic" aria-hidden="true">
 <!-- Map / pin -->
 <svg viewBox="0 0 24 24"><path d="M12 21s7-4.4 7-11a7 7 0 1 0-14 0c0 6.6 7 11 7 11Z"/><path d="M12 10a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg>
 </span>Guide Map
 </a>

 </div>
</nav>


