document.addEventListener('DOMContentLoaded', function () {
 const nav = document.querySelector('.ep-tabs');
 if (!nav) return;

 const baseOffset = parseInt(nav.getAttribute('data-offset') || '110', 10);

 const SHOW_AFTER = 200; // 200px पछि मात्र देखाउने
 const CLICK_GAP = 40; // click गर्दा extra gap
 const ACTIVE_GAP = 12; // active detect line tuning

 const links = Array.from(nav.querySelectorAll('a[href^="#"]'));
 if (!links.length) return;

 const isVisible = (el) => {
 if (!el) return false;
 const st = window.getComputedStyle(el);
 return st.display !== 'none' && st.visibility !== 'hidden' && el.offsetHeight > 0;
 };

 // Build valid items
 let items = [];
 const build = () => {
 items = links.map(a => {
 const id = a.getAttribute('href').slice(1);
 const section = document.getElementById(id);

 if (!isVisible(section)) {
 a.style.display = 'none';
 return null;
 }
 a.style.display = '';
 return { id, link: a, section };
 }).filter(Boolean);

 if (!items.length) nav.style.display = 'none';
 };

 const setActive = (id) => {
 items.forEach(it => it.link.classList.toggle('is-active', it.id === id));
 };

 const navH = () => (nav.getBoundingClientRect().height || 0);

 // click offset: tabs + baseOffset + 100px gap
 const clickOffset = () => navH() + baseOffset + CLICK_GAP;

 // active trigger line: tabs + baseOffset (small)
 const triggerY = () => navH() + baseOffset + ACTIVE_GAP;

 // initial
 nav.style.display = 'none';
 build();
 if (!items.length) return;
 setActive(items[0].id);

 // click scroll (smooth + exact offset)
 items.forEach(it => {
 it.link.addEventListener('click', (e) => {
 e.preventDefault();
 const y = it.section.getBoundingClientRect().top + window.pageYOffset - clickOffset();
 setActive(it.id);
 window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
 });
 });

 // Smooth scrollspy: choose closest section to trigger line
 let ticking = false;
 const onScroll = () => {
 if (ticking) return;
 ticking = true;

 requestAnimationFrame(() => {
 ticking = false;

 // show after 200px
 if (window.scrollY <= SHOW_AFTER) {
 nav.style.display = 'none';
 return;
 }

 const vh = window.innerHeight || 0;
 const line = triggerY();

 // hide if none visible on screen
 const anyVisible = items.some(it => {
 const r = it.section.getBoundingClientRect();
 return (r.bottom > line) && (r.top < vh - 40);
 });
 if (!anyVisible) {
 nav.style.display = 'none';
 return;
 }

 nav.style.display = '';

 // find closest section to trigger line
 let bestId = items[0].id;
 let bestDist = Infinity;

 for (const it of items) {
 const r = it.section.getBoundingClientRect();
 // distance from trigger line to section top
 const dist = Math.abs(r.top - line);
 if (dist < bestDist) {
 bestDist = dist;
 bestId = it.id;
 }
 }

 setActive(bestId);
 });
 };

 window.addEventListener('scroll', onScroll, { passive: true });
 window.addEventListener('resize', () => { build(); onScroll(); }, { passive: true });

 // Elementor late render
 setTimeout(() => { build(); onScroll(); }, 400);
 setTimeout(() => { build(); onScroll(); }, 1200);

 onScroll();
});
</script>","jedv_conditions":[{"_id":"59a1b91"}]},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"ed1675a","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#F8FFFF","padding":{"unit":"px","top":"30","right":"10","bottom":"30","left":"10","isLinked":false},"jedv_conditions":[{"_id":"e1fe054"}],"__globals__":{"background_color":""}},"elements":[{"id":"500494d","elType":"container","settings":{"content_width":"full","flex_gap":{"column":"5","row":"5","isLinked":true,"unit":"px","size":5},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"jedv_conditions":[{"_id":"e835ac8"}]},"elements":[{"id":"81240a7","elType":"widget","settings":{"content_width":"full","title":"You May Also Like --------","jedv_conditions":[{"_id":"ca28b95","jedv_condition":"not-exists","__dynamic__":{"jedv_field":"[elementor-tag id="9903cbb" name="jet-post-custom-field" settings="%7B%22meta_field%22%3A%22package-include%22%7D"]"}}],"jedv_type":"hide","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Open Sans","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":15,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"heading"},{"id":"96380c8","elType":"widget","settings":{"title":"Similar Itineraries","header_size":"h5","typography_typography":"custom","typography_font_family":"Open Sans","typography_font_size":{"unit":"px","size":25,"sizes":[]},"typography_font_weight":"600","jedv_conditions":[{"_id":"9bbee3d"}],"typography_font_size_tablet":{"unit":"px","size":22,"sizes":[]},"__globals__":{"title_color":"globals/colors?id=text","typography_typography":""},"typography_font_size_mobile":{"unit":"px","size":20,"sizes":[]},"typography_line_height":{"unit":"em","size":1.4,"sizes":[]},"typography_line_height_tablet":{"unit":"em","size":1.8,"sizes":[]},"typography_line_