{"timeout":1787524035,"value":{"content":"[elementor-element k="eca0028d20cbc58bfaeb1e3a94099338" data=""]<div class="elementor-element elementor-element-89ad8ae e-con-full e-flex e-con e-parent" data-id="89ad8ae" data-element_type="container" data-e-type="container">
				<div data-flyup-qe-widget-name="html" data-flyup-qe-object-type="post" data-flyup-qe-object-id="15182" data-flyup-qe-post-id="15182" data-flyup-qe-widget-id="821d296" class="elementor-element elementor-element-821d296 ep-scroll-section elementor-widget elementor-widget-html" data-id="821d296" data-element_type="widget" data-e-type="widget" data-settings="{&quot;sticky&quot;:&quot;top&quot;,&quot;sticky_offset&quot;:83,&quot;sticky_on&quot;:[&quot;desktop&quot;,&quot;tablet&quot;,&quot;mobile&quot;],&quot;sticky_effects_offset&quot;:0,&quot;sticky_anchor_link_offset&quot;:0}" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<style>
 /* =========================================================
 EVER PEAK – Sticky Tabs (Light Blue, Full-width, Compact)
 matches screenshot + works with .is-active
 ========================================================= */

.ep-tabs{
 --bg1:#e9f6ff;
 --bg2:#d8f0ff;
 --pill:#ffffff;
 --pillLine:#cfe9ff;
 --text:#0b1b33;
 --muted:#5a6a80;
 --active1:#19a8ff;
 --active2:#0b79d0;
 --shadow:0 10px 22px rgba(2,20,46,.10);

 position: sticky;
 top: 0;
 z-index: 999;

 width: 100%;
 max-width: 1180px;
 margin: 0 auto 10px;

 /* make height small */
 padding: 5px 0;
 background: transparent;
 isolation:isolate;
}

/* Full width background bar */
.ep-tabs::before{
 content:"";
 position:absolute;
 left:50%;
 transform:translateX(-50%);
 top:0;
 width:100vw;
 height:100%;
 background: linear-gradient(180deg, var(--bg1), var(--bg2));
 border-bottom: 1px solid #cfe9ff;
 box-shadow: var(--shadow);
 backdrop-filter: blur(6px);
 -webkit-backdrop-filter: blur(6px);
 z-index:-1;
}

/* row */
.ep-tabs .ep-tabs-row{
 display:flex;
 gap:8px;
 align-items:center;
 overflow-x:auto;
 padding: 0 10px;
 scrollbar-width:none;
}
.ep-tabs .ep-tabs-row::-webkit-scrollbar{ display:none; }

/* tab link (compact height) */
.ep-tabs a{
 display:inline-flex;
 align-items:center;
 gap:7px;

 padding: 6px 10px; /* 👈 smaller height */
 border-radius: 999px;
 background: var(--pill);
 border:1px solid var(--pillLine);

 text-decoration:none;
 white-space:nowrap;

 font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
 font-size: 13px; /* 👈 slightly smaller */
 font-weight: 650;
 color: var(--muted);

 transition: background .18s ease, border-color .18s ease, color .18s ease, transform .18s ease, box-shadow .18s ease;
}

.ep-tabs a:hover{
 background:#f3faff;
 color: var(--text);
 border-color:#b9dcff;
 transform: translateY(-1px);
}

/* active tab (force win) */
.ep-tabs a.is-active{
 background: linear-gradient(180deg, var(--active1), var(--active2)) !important;
 color:#fff !important;
 border-color: var(--active2) !important;
 box-shadow: 0 8px 14px rgba(11,121,208,.22) !important;
 transform:none !important;
}

/* icon (smaller) */
.ep-tabs .ep-ic{
 width:18px;
 height:18px;
 display:inline-flex;
 align-items:center;
 justify-content:center;
 border-radius:50%;
 background:#eaf6ff;
 border:1px solid #cfe9ff;
 flex:0 0 18px;
}

.ep-tabs a.is-active .ep-ic{
 background: rgba(255,255,255,.25) !important;
 border-color: rgba(255,255,255,.35) !important;
}

.ep-tabs .ep-ic svg{
 width:12px;
 height:12px;
 fill:none;
 stroke: currentColor;
 stroke-width:2.2;
 stroke-linecap:round;
 stroke-linejoin:round;
}

/* section helper (optional) */
.ep-scroll-section{
 scroll-margin-top: 220px; /* adjust if needed */
}

/* mobile */
@media (max-width:640px){
 .ep-tabs{ padding:4px 0; margin-bottom:8px; }
 .ep-tabs a{ padding:6px 9px; font-size:12.5px; }
