<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
.ep-all-inclusive{

 --primary:#1E293B;
 --secondary:#1E293B;
 --text:#1E293B;
 --accent:#F59E0B;
 --background:#F8FAFC;

 font-family:'Inter',sans-serif;
 max-width:720px;
 margin:0 auto;
}

/* Card */

.ep-all-inclusive .ai-card{
 position:relative;
 padding:28px 24px 22px;
 border-radius:20px;
 background:linear-gradient(145deg,var(--primary),var(--secondary));
 border:1px solid rgba(255,255,255,.18);
 overflow:hidden;
 box-shadow:0 20px 50px rgba(30,41,59,.18);
}

/* Glow */

.ep-all-inclusive .ai-card::before{
 content:"";
 position:absolute;
 left:-80px;
 top:-80px;
 width:240px;
 height:240px;
 background:radial-gradient(circle,rgba(255,255,255,.18),transparent 70%);
}

/* Heading */

.ep-all-inclusive .ai-title{
 margin:0;
 text-align:center;
 font-family:'Montserrat',sans-serif;
 font-size:30px;
 font-weight:800;
 color:var(--accent);
}

.ep-all-inclusive .ai-sub{
 margin:10px 0 22px;
 text-align:center;
 color:rgba(255,255,255,.88);
 font-size:15px;
}

/* List */

.ep-all-inclusive .ai-list{
 list-style:none;
 padding:0;
 margin:0;
 display:grid;
 gap:14px;
}

/* Item */

.ep-all-inclusive .ai-item{
 display:flex;
 align-items:center;
 gap:14px;
 background:rgba(248,250,252,.14);
 border:1px solid rgba(255,255,255,.15);
 padding:15px 16px;
 border-radius:14px;
 transition:.3s ease;
 backdrop-filter:blur(8px);
}

.ep-all-inclusive .ai-item:hover{
 transform:translateY(-3px);
 background:rgba(248,250,252,.22);
 border-color:rgba(245,158,11,.45);
}

/* Icon */

.ep-all-inclusive .ai-ic{
 width:42px;
 height:42px;
 flex:0 0 42px;
 border-radius:50%;
 display:flex;
 align-items:center;
 justify-content:center;
 background:rgba(245,158,11,.12);
 border:1px solid rgba(245,158,11,.45);
}

.ep-all-inclusive .ai-ic svg{
 width:20px;
 height:20px;
 stroke:var(--accent);
 stroke-width:2.4;
 fill:none;
 stroke-linecap:round;
 stroke-linejoin:round;
}

/* Text */

.ep-all-inclusive .ai-text{
 color:#fff;
 font-size:17px;
 font-weight:700;
 line-height:1.3;
}

/* Footer */

.ep-all-inclusive .ai-note{
 margin-top:18px;
 text-align:center;
 color:rgba(255,255,255,.82);
 font-size:13px;
}

/* Mobile */

@media(max-width:576px){

.ep-all-inclusive .ai-card{
 padding:22px 18px;
}

.ep-all-inclusive .ai-title{
 font-size:24px;
}

.ep-all-inclusive .ai-text{
 font-size:15px;
}

}
</style>

<div class="ep-all-inclusive">

<div class="ai-card">

<h3 class="ai-title">All Inclusive Price</h3>

<p class="ai-sub">
Everything you need, with clear and secure booking.
</p>

<ul class="ai-list">

<li class="ai-item">

<span class="ai-ic">

<svg viewBox="0 0 24 24">
<path d="M12 22a10 10 0 1 0-10-10 10 10 0 0 0 10 10Z"/>
<path d="M10 8l4 4-4 4"/>
</svg>

</span>

<span class="ai-text">
Instant Booking
</span>

</li>

<li class="ai-item">

<span class="ai-ic">

<svg viewBox="0 0 24 24">
<path d="M12 2l8 4v6c0 5-3.2 9.4-8 10-4.8-.6-8-5-8-10V6l8-4Z"/>
<path d="M9 12l2 2 4-5"/>
</svg>

</span>

<span class="ai-text">
Secure Payments
</span>

</li>

<li class="ai-item">

<span class="ai-ic">

<svg viewBox="0 0 24 24">
<path d="M20 12l-8 8-10-10V2h8l10 10Z"/>
<path d="M7.5 7.5h.01"/>
</svg>

</span>

<span class="ai-text">
No Hidden Costs
</span>

</li>

</ul>

<p class="ai-note">
Transparent Pricing • Fast Confirmation • Trusted Support
</p>

</div>

</div>				</div>
