				<div data-flyup-qe-widget-name="html" data-flyup-qe-object-type="post" data-flyup-qe-object-id="15182" data-flyup-qe-post-id="15182" data-flyup-qe-widget-id="baf6f17" class="elementor-element elementor-element-baf6f17 elementor-widget elementor-widget-html" data-id="baf6f17" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<script>
document.addEventListener('DOMContentLoaded', function () {
 const nav = document.querySelector('.ep-tabs');
 if (!nav) return;

 const baseOffset = parseInt(nav.getAttribute('data-offset') || '110', 10);

 const SHOW_AFTER = 200; // 200px पछि मात्र देखाउने
 const CLICK_GAP = 40; // click गर्दा extra gap
 const ACTIVE_GAP = 12; // active detect line tuning

 const links = Array.from(nav.querySelectorAll('a[href^="#"]'));
 if (!links.length) return;

 const isVisible = (el) => {
 if (!el) return false;
 const st = window.getComputedStyle(el);
 return st.display !== 'none' && st.visibility !== 'hidden' && el.offsetHeight > 0;
 };

 // Build valid items
 let items = [];
 const build = () => {
 items = links.map(a => {
 const id = a.getAttribute('href').slice(1);
 const section = document.getElementById(id);

 if (!isVisible(section)) {
 a.style.display = 'none';
 return null;
 }
 a.style.display = '';
 return { id, link: a, section };
 }).filter(Boolean);

 if (!items.length) nav.style.display = 'none';
 };

 const setActive = (id) => {
 items.forEach(it => it.link.classList.toggle('is-active', it.id === id));
 };

 const navH = () => (nav.getBoundingClientRect().height || 0);

 // click offset: tabs + baseOffset + 100px gap
 const clickOffset = () => navH() + baseOffset + CLICK_GAP;

 // active trigger line: tabs + baseOffset (small)
 const triggerY = () => navH() + baseOffset + ACTIVE_GAP;

 // initial
 nav.style.display = 'none';
 build();
 if (!items.length) return;
 setActive(items[0].id);

 // click scroll (smooth + exact offset)
 items.forEach(it => {
 it.link.addEventListener('click', (e) => {
 e.preventDefault();
 const y = it.section.getBoundingClientRect().top + window.pageYOffset - clickOffset();
 setActive(it.id);
 window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
 });
 });

 // Smooth scrollspy: choose closest section to trigger line
 let ticking = false;
 const onScroll = () => {
 if (ticking) return;
 ticking = true;

 requestAnimationFrame(() => {
 ticking = false;

 // show after 200px
 if (window.scrollY <= SHOW_AFTER) {
 nav.style.display = 'none';
 return;
 }

 const vh = window.innerHeight || 0;
 const line = triggerY();

 // hide if none visible on screen
 const anyVisible = items.some(it => {
 const r = it.section.getBoundingClientRect();
 return (r.bottom > line) && (r.top < vh - 40);
 });
 if (!anyVisible) {
 nav.style.display = 'none';
 return;
 }

 nav.style.display = '';

 // find closest section to trigger line
 let bestId = items[0].id;
 let bestDist = Infinity;

 for (const it of items) {
 const r = it.section.getBoundingClientRect();
 // distance from trigger line to section top
 const dist = Math.abs(r.top - line);
 if (dist < bestDist) {
 bestDist = dist;
 bestId = it.id;
 }
 }

 setActive(bestId);
 });
 };

 window.addEventListener('scroll', onScroll, { passive: true });
 window.addEventListener('resize', () => { build(); onScroll(); }, { passive: true });

 // Elementor late render
 setTimeout(() => { build(); onScroll(); }, 400);
 setTimeout(() => { build(); onScroll(); }, 1200);

 onScroll();
});
</script>				</div>
