ked":true},"jedv_conditions":[{"_id":"063f075"}],"flex_justify_content":"center"},"elements":[{"id":"3d2a345","elType":"widget","settings":{"html":"<!-- Blowing Animated Video Play Button -->
<div class="video-play-button">
 <div class="glow"></div>
 <div class="circle"></div>
 <div class="triangle"></div>
 <div class="wave wave1"></div>
 <div class="wave wave2"></div>
 <div class="wave wave3"></div>
</div>

<style>
.video-play-button {
 position: relative;
 width: 120px;
 height: 120px;
 cursor: pointer;
 display: flex;
 justify-content: center;
 align-items: center;
 perspective: 600px;
 transform-style: preserve-3d;
 background: transparent;
}

/* Central Glow */
.video-play-button .glow {
 position: absolute;
 width: 140%;
 height: 140%;
 border-radius: 50%;
 background: radial-gradient(circle, rgba(255,150,150,0.2), rgba(255,255,255,0));
 filter: blur(20px);
 animation: glowAnim 2s infinite alternate;
 z-index: 0;
}

/* Main Circle */
.video-play-button .circle {
 position: absolute;
 width: 100%;
 height: 100%;
 border-radius: 50%;
 border: 3px solid transparent;
 background: conic-gradient(
 rgba(255,120,120,0.3),
 rgba(120,200,255,0.3),
 rgba(120,255,200,0.3),
 rgba(255,120,120,0.3)
 );
 animation: rotateCircle 5s linear infinite;
 z-index: 1;
}

/* Play Triangle */
.video-play-button .triangle {
 position: relative;
 width: 0;
 height: 0;
 border-left: 35px solid #ffffff;
 border-top: 20px solid transparent;
 border-bottom: 20px solid transparent;
 z-index: 3;
 filter: drop-shadow(0 0 15px rgba(255,255,255,0.8));
 transform: translateZ(5px);
}

/* Waves */
.video-play-button .wave {
 position: absolute;
 width: 100%;
 height: 100%;
 border-radius: 50%;
 border: 2px solid rgba(255,120,120,0.2);
 animation: waveAnim 3s infinite;
 z-index: 0;
}

.video-play-button .wave1 {
 animation-duration: 3s;
 transform: scale(1.05);
 border-color: rgba(120,200,255,0.25);
}

.video-play-button .wave2 {
 animation-duration: 4s;
 transform: scale(1.15);
 border-color: rgba(120,255,200,0.25);
}

.video-play-button .wave3 {
 animation-duration: 5s;
 transform: scale(1.3);
 border-color: rgba(255,150,150,0.15);
}

/* Animations */
@keyframes rotateCircle {
 0% { transform: rotateX(0deg) rotateY(0deg); }
 100% { transform: rotateX(360deg) rotateY(360deg); }
}

@keyframes waveAnim {
 0% { transform: scale(1); opacity: 0.5; }
 50% { transform: scale(1.5); opacity: 0.2; }
 100% { transform: scale(1); opacity: 0.5; }
}

@keyframes glowAnim {
 0% { transform: scale(1); opacity: 0.5; }
 100% { transform: scale(1.2); opacity: 1; }
}
</style>
