"isLinked":true,"unit":"px","size":0},"background_background":"classic","background_color":"#F1FEFF","border_radius":{"unit":"px","top":"25","right":"25","bottom":"25","left":"25","isLinked":true},"box_shadow_box_shadow_type":"yes","box_shadow_box_shadow":{"horizontal":17,"vertical":-7,"blur":17,"spread":0,"color":"rgba(93.58637718532397, 110.15290979266393, 111.81748962402345, 0.5)"},"margin":{"unit":"px","top":"16","right":"0","bottom":"0","left":"0","isLinked":false},"css_classes":"trip-keypoints","jedv_conditions":[{"_id":"7411df4"}],"custom_css":"/* ==========================================
   Trip Keypoints – SAME AS TOP
   ONLY kp-value box removed
   ========================================== */

.trip-keypoints{
  --blue:#2563eb;
  --sky:#eaf5ff;
  --sky2:#f4fbff;
  --sky-border:#bfe3ff;

  --text:#0f172a;
  --muted:#64748b;

  --note-bg:#f4f9ff;
  --note-border:#bfe3ff;

  width:100%;
  padding:5px;
  background:#ffffff;
  border:1px solid #dbeeff;
  border-radius:18px;
  box-shadow:0 12px 30px rgba(2,32,71,.08);
  box-sizing:border-box;
}

/* =========================
   GRID (4 cards)
   ========================= */
.trip-keypoints .kp-grid{
  display:flex;
  gap:12px;
  width:100%;
  flex-wrap:nowrap;
  box-sizing:border-box;
}

.trip-keypoints .kp-card{
  flex:1 1 0;
  min-width:0;
  background:linear-gradient(180deg,#ffffff,var(--sky2));
  border:1px solid var(--sky-border);
  border-radius:14px;
  padding:14px;
  box-shadow:0 8px 18px rgba(2,32,71,.08);
  box-sizing:border-box;
}

/* =========================
   TITLE (icon + label)
   ========================= */
.trip-keypoints .kp-title{
  display:flex;
  align-items:center;
  justify-content:center;   /* CENTER horizontally */
  gap:10px;

  font-size:14px;
  font-weight:800;
  color:#1e40af;

  padding-bottom:8px;
  margin:0 0 10px 0;

  border-bottom:1px dashed #c7ddff;
  text-align:center;        /* text center fallback */
}

.trip-keypoints .kp-title span,
.trip-keypoints .kp-title i{
  display:inline-flex;
  align-items:center;
  justify-content:center;

  width:26px;
  height:26px;
  border-radius:8px;

  background:#eaf2ff;
  border:1px solid #c7ddff;
  color:#2563eb;

  font-size:14px;
  flex-shrink:0;
}

/* =========================
   VALUE (Dynamic Field)
   BOX REMOVED ✔
   ========================= */
.trip-keypoints .kp-value{
  display:block;
  width:100%;

  /* BOX REMOVED */
  background:none;
  border:none;
  border-radius:0;
  padding:4px 0;

  font-size:15px;       /* FIRST LINE BIG */
  font-weight:600;
  color:var(--text);
  line-height:1.35;
  word-break:break-word;
}

/* remove <p> margin from JetEngine */
.trip-keypoints .kp-value p{
  margin:0;
}

/* SECOND LINE (altitude / km etc.) */
.trip-keypoints .kp-value span,
.trip-keypoints .kp-value small,
.trip-keypoints .kp-value .kp-sub{
  display:block;
  margin-top:2px;
  font-size:12px;
  font-weight:600;
  color:var(--muted);
}

/* =========================
   NOTE BOX
   ========================= */
.trip-keypoints .kp-note{
  margin-top:16px;
  background:linear-gradient(180deg,#f7fbff,var(--note-bg));
  border:1px solid var(--note-border);
  border-radius:16px;
  padding:16px;
  box-shadow:0 10px 22px rgba(2,32,71,.08);
  box-sizing:border-box;
}

.trip-keypoints .kp-note-title{
  font-size:15px;
  font-weight:900;
  color:var(--text);
  display:flex;
  align-items:center;
  gap:10px;
  margin:0 0 6px 0;
}

.trip-keypoints .kp-note-desc{
  font-size:13px;
  color:#334155;
  line-height:1.55;
}
.trip-keypoints .kp-note-desc p{ margin:0; }

/* =========================
   RESPONSIVE
   ========================= */
@media(max-width:900px){
  .trip-keypoints .kp-grid{
    flex-wrap:wrap;
  }
  .trip-keypoints .kp-card{
    flex:0 0 calc(50% - 6px);
  }
}

@media(max-width:600px){
  .trip-keypoints .kp-card{
    flex:0 0 100%;
  }
