sLinked":true},"_border_color":"#F0DADA","_border_radius":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":true},"field_alignment":"center"},"elements":[],"widgetType":"jet-listing-dynamic-field"}],"isInner":true}],"isInner":true},{"id":"c5a6c8f","elType":"container","settings":{"content_width":"full","flex_direction":"row","css_classes":"kp-note","jedv_conditions":[{"_id":"b9dfc69"}]},"elements":[{"id":"7ffec72","elType":"container","settings":{"content_width":"full","flex_gap":{"column":"7","row":"7","isLinked":true,"unit":"px","size":7},"background_background":"classic","border_border":"none","box_shadow_box_shadow":{"horizontal":0,"vertical":0,"blur":3,"spread":0,"color":"rgba(0,0,0,0.5)"},"jedv_conditions":[{"_id":"b9dfc69"}],"_element_width":"initial"},"elements":[{"id":"52a9684","elType":"widget","settings":{"title":"⚠️ Important Note","typography_typography":"custom","typography_font_family":"Lato","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_line_height":{"unit":"em","size":"","sizes":[]},"title_color":"#0A516E","_css_classes":"kp-note-title","jedv_conditions":[{"_id":"7d4ddcd"}]},"elements":[],"widgetType":"heading"},{"id":"65d8e31","elType":"widget","settings":{"dynamic_field_source":"repeater_field","dynamic_excerpt_more":"...","dynamic_field_post_meta_custom":"important_note","date_format":"F j, Y","num_dec_point":".","num_thousands_sep":",","multiselect_delimiter":", ","dynamic_field_format":"%s","jedv_conditions":[{"_id":"0227de5"}],"field_typography_typography":"custom","field_typography_font_size":{"unit":"px","size":20,"sizes":[]},"_padding":{"unit":"px","top":"20","right":"0","bottom":"20","left":"0","isLinked":false},"custom_css":"/* ==============================
   Trip Keypoints – FINAL FLEX
   4 columns | altitude next line
   ============================== */

.trip-keypoints{
  --blue:#2563eb;
  --sky:#eaf5ff;
  --sky2:#f4fbff;
  --sky-border:#bfe3ff;

  --warn-bg:#fff7e6;
  --warn-border:#ffd08a;
  --icon:#f59e0b;

  --text:#0f172a;
  --muted:#64748b;

  width:100%;
  padding:22px;
  background:#ffffff;
  border:1px solid #dbeeff;
  border-radius:18px;
  box-shadow:0 12px 30px rgba(2,32,71,.08);
  box-sizing:border-box;
}

/* TOP ROW – FORCE ONE LINE */
.trip-keypoints .kp-grid{
  display:flex;
  flex-wrap:nowrap;
  gap:12px;
  width:100%;
  box-sizing:border-box;
}

/* EACH COLUMN – TRUE 25% */
.trip-keypoints .kp-item{
  flex:0 0 calc(25% - 9px);
  max-width:calc(25% - 9px);
  min-width:0;
  display:flex;
  align-items:center;
  gap:10px;
  box-sizing:border-box;
}

/* ICON */
.trip-keypoints .kp-icon{
  width:40px;
  height:40px;
  border-radius:12px;
  background:linear-gradient(180deg,var(--sky2),var(--sky));
  border:1px solid var(--sky-border);
  color:var(--blue);
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:18px;
  flex-shrink:0;
}

/* TEXT */
.trip-keypoints .kp-label{
  font-size:13px;
  font-weight:600;
  color:var(--blue);
  line-height:1.15;
}

.trip-keypoints .kp-value{
  font-size:15px;
  font-weight:800;
  color:var(--text);
  line-height:1.15;
  white-space:normal;     /* allow next line */
}

/* ALTITUDE – NEXT LINE */
.trip-keypoints .kp-alt{
  display:block;
  margin-top:2px;
  font-size:12px;
  font-weight:600;
  color:var(--muted);
}

/* WARNING BOX */
.trip-keypoints .kp-warning{
  margin-top:18px;
  display:flex;
  gap:12px;
  padding:14px;
  background:#f4f9ff;
  border:1px solid #bfe3ff;
  border-radius:16px;
  box-sizing:border-box;
}

.trip-keypoints .kp-w-icon{
  width:38px;
  height:38px;
  border-radius:12px;
  background:var(--warn-bg);
  border:1px solid var(--warn-border);
  color:var(--icon);
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:16px;
  flex-shrink:0;
}

.trip-keypoints .kp-w-title{
  font-size:15px;
  font-weight:900;
  color:var(--text);
}

.trip-keypoints .kp-w-desc{
  font-size:13px;
  color:#334155;
  margin-top:4px;
  line-height:1.45;
}

/* MOBILE */
@media(max-width:768px){
  .trip-keypoints .kp-grid{
    flex-wrap:wrap;
    gap:14px;
  }
  .trip-keypoints .kp-item{
    flex:0 0 100%;
    max-width:100%;
  }
}","_css_classes":"kp-note-desc","field_typography_font_style":"italic"},"elements":[],"widgetType":"jet-listing-dynamic-field"}],"isInner":true}],"isInner":true}],"isInner":true}],"isInner":false},{"id":"069469e","elType":"container","settings":{"flex_direction":"column","_element_id":"itinerary-content","css_classes":"itinerary-content","jedv_conditions":[{"_id":"498038c"}]},"elements":[],"isInner":false}]

