    padding: clamp(18px, 2.8vw, 34px);
    border-radius: 18px;
  }

  .epa-rt *{ box-sizing: border-box; }

  .epa-rt-card{
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 18px;
    box-shadow: var(--shadow);
    overflow: hidden;
  }

  .epa-rt-head{
    position: relative;
    padding: clamp(18px, 2.6vw, 26px);
    border-bottom: 1px solid var(--line);
