  .epa-rt-title{
    position: relative;
    display:flex;
    align-items:flex-start;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
  }

  .epa-rt-title h2{
    margin:0;
    font-size: clamp(20px, 2.4vw, 30px);
