    border-radius: 999px;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
  }

  .epa-rt-body{
    padding: clamp(18px, 2.8vw, 30px);
    display: grid;
    grid-template-columns: 1.05fr .95fr;
    gap: clamp(16px, 2.6vw, 26px);
