  .epa-rt-aside{
    border: 1px solid var(--line);
    border-radius: 16px;
    background:
      radial-gradient(700px 220px at 20% 0%, rgba(42,151,189,.14) 0%, rgba(42,151,189,0) 55%),
      linear-gradient(180deg, rgba(27,43,85,.04), rgba(42,151,189,.06));
