  .epa-rt-aside h3{
    margin: 0 0 10px 0;
    font-size: 16px;
    font-weight: 500;
    color: var(--brand-dark);
  }

  .epa-rt-points{
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    gap: 10px;
  }

  .epa-rt-point{
    display:flex;
    gap: 10px;
    align-items:flex-start;
    padding: 10px 10px;
    background: rgba(255,255,255,.75);
    border: 1px solid rgba(15,23,42,.08);
    border-radius: 12px;
  }

  .epa-rt-ico{
    width: 26px;
    height: 26px;
    border-radius: 10px;
    display:flex;
    align-items:center;
    justify-content:center;
    background: rgba(42,151,189,.12);
    border: 1px solid rgba(42,151,189,.22);
