[{"id":"0eb7d4a","elType":"container","settings":{"flex_direction":"column","jedv_conditions":[{"_id":"5d8ed61"}]},"elements":[{"id":"63f6d65","elType":"widget","settings":{"html":"<style>
/*====================================================
   EVER PEAK ADVENTURES - FOUNDER MESSAGE
   Updated with New Global Colors
====================================================*/

.epa-founder-wrap{
    --primary:#494641;
    --secondary:#38BDF8;
    --text:#1E293B;
    --accent:#F59E0B;
    --background:#F8FAFC;

    --card:#ffffff;
    --muted:#64748B;
    --line:rgba(30,41,59,.10);
    --shadow:0 18px 45px rgba(30,41,59,.12);

    font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
    color:var(--text);

    background:
    radial-gradient(900px 260px at 20% 0%,rgba(56,189,248,.16) 0%,rgba(56,189,248,0) 60%),
    radial-gradient(900px 260px at 80% 0%,rgba(245,158,11,.12) 0%,rgba(245,158,11,0) 60%),
    linear-gradient(180deg,var(--background) 0%,#fff 75%);

    padding:clamp(18px,2.8vw,34px);
    border-radius:18px;
}

/* Card */

.epa-founder-card{
    background:#fff;
    border:1px solid var(--line);
    border-radius:18px;
    overflow:hidden;
    box-shadow:var(--shadow);
}

/* Header */

.epa-founder-head{
    position:relative;
    padding:clamp(20px,2.6vw,28px);
    border-bottom:1px solid var(--line);
}

.epa-founder-head::before{
    content:"";
    position:absolute;
    inset:0;
    background:linear-gradient(90deg,
    rgba(56,189,248,.18),
    rgba(245,158,11,.10));
}

.epa-founder-title{
    position:relative;
    display:flex;
    justify-content:space-between;
    align-items:flex-start;
    flex-wrap:wrap;
    gap:15px;
}

.epa-founder-title h2{
    margin:0;
    font-size:clamp(24px,2.8vw,34px);
    font-weight:900;
    color:var(--primary);
}

.epa-slogan{
    margin-top:6px;
    color:var(--primary);
    font-size:15px;
    font-weight:700;
}

.epa-founder-badge{
    padding:9px 14px;
    border-radius:100px;
    background:rgba(245,158,11,.12);
    border:1px solid rgba(245,158,11,.28);
    color:var(--primary);
    font-weight:800;
    font-size:13px;
}

/* Body */

.epa-founder-body{
    display:grid;
    grid-template-columns:280px 1fr;
    gap:30px;
    padding:30px;
}

/* Profile */

.epa-founder-profile{
    position:sticky;
    top:20px;
}

.epa-founder-photo{
    overflow:hidden;
    border-radius:18px;
    border:3px solid rgba(56,189,248,.45);
    box-shadow:0 18px 40px rgba(30,41,59,.15);
    background:#E0F7FF;
}

.epa-founder-photo img{
    width:100%;
    display:block;
    aspect-ratio:4/5;
