				<div class="elementor-element elementor-element-08d5a52 elementor-widget elementor-widget-html" data-id="08d5a52" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<style>
/*==============================
 WHY CHOOSE US
==============================*/

.epa-why{
    --primary:#494641;
    --secondary:#38BDF8;
    --text:#1E293B;
    --accent:#F59E0B;
    --bg:#F8FAFC;

    /*padding:90px 20px;*/
    background:linear-gradient(180deg,#F8FAFC 0%,#ffffff 100%);
    font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
}

.epa-why-container{
    max-width:1200px;
    margin:auto;
}

.epa-why-header{
    text-align:center;
    max-width:760px;
    margin:0 auto 60px;
}

.epa-why-subtitle{
    display:inline-block;
    padding:8px 18px;
    background:rgba(56,189,248,.12);
    color:var(--secondary);
    border-radius:30px;
    font-size:14px;
    font-weight:700;
    letter-spacing:.5px;
    margin-bottom:18px;
}

.epa-why-header h2{
    margin:0;
    font-size:clamp(34px,5vw,48px);
    color:var(--primary);
    font-weight:800;
}

.epa-why-header h2 span{
    color:var(--accent);
}

.epa-why-header p{
    margin-top:18px;
    color:#64748B;
    font-size:17px;
    line-height:1.8;
}

.epa-why-grid{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:28px;
}

.epa-card{
    background:#fff;
    border:1px solid rgba(30,41,59,.08);
    border-radius:22px;
    padding:35px 30px;
    transition:.35s;
    position:relative;
    overflow:hidden;
    box-shadow:0 12px 35px rgba(15,23,42,.05);
}

.epa-card:before{
    content:"";
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:4px;
    background:linear-gradient(90deg,var(--secondary),var(--accent));
    transform:scaleX(0);
    transform-origin:left;
    transition:.35s;
}

.epa-card:hover{
    transform:translateY(-10px);
    box-shadow:0 22px 50px rgba(15,23,42,.12);
}

.epa-card:hover:before{
    transform:scaleX(1);
}

.epa-icon{
    width:72px;
    height:72px;
    border-radius:18px;
    display:flex;
    align-items:center;
    justify-content:center;
    background:linear-gradient(135deg,var(--secondary),#67D4FF);
    color:#fff;
    font-size:32px;
    margin-bottom:22px;
}

.epa-card h3{
    margin:0 0 14px;
    color:var(--primary);
    font-size:23px;
    font-weight:700;
}

.epa-card p{
    margin:0;
    color:var(--text);
    line-height:1.8;
    font-size:15px;
}

@media(max-width:991px){

.epa-why-grid{
grid-template-columns:repeat(2,1fr);
}

}

@media(max-width:767px){

.epa-why{
padding:70px 18px;
}

.epa-why-grid{
grid-template-columns:1fr;
}

.epa-card{
padding:30px 25px;
}

}
</style>

