.ep-ta4{
  --bg1:#061421;
  --bg2:#0a2a20;
  --stroke:rgba(255,255,255,.14);
  --text:rgba(255,255,255,.94);
  --muted:rgba(255,255,255,.74);
  --pill:rgba(255,255,255,.10);
  --green:#00aa6c;
  --green2:#00d084;

  border-radius:22px;
  border:1px solid var(--stroke);
  background:
    radial-gradient(900px 280px at 15% 15%, rgba(0,208,132,.18), transparent 55%),
    radial-gradient(700px 260px at 90% 40%, rgba(255,255,255,.10), transparent 60%),
    linear-gradient(135deg,var(--bg1),var(--bg2));
  box-shadow: 0 18px 45px rgba(0,0,0,.25);
  overflow:hidden;
}

/* Desktop layout */
.ep-ta4-inner{
  display:grid;
  grid-template-columns: 420px 1fr auto; /* logos | text | cta */
  gap:18px;
  align-items:center;
  padding:18px;
  min-height:140px;
  box-sizing:border-box;
}

/* Logo card is a grid to prevent overlap */
.ep-ta4-logos{
  display:grid;
  grid-template-columns: 1fr 1px 160px; /* company | divider | tripadvisor */
  align-items:center;
  gap:14px;
  padding:12px 14px;
  border-radius:18px;
  background: rgba(255,255,255,.06);
  border:1px solid rgba(255,255,255,.12);
  backdrop-filter: blur(6px);
  overflow:hidden; /* IMPORTANT */
  width:100%;
  max-width:420px;
  box-sizing:border-box;
}

.ep-ta4-logo-col{
  min-width:0;        /* IMPORTANT for grid */
  overflow:hidden;    /* IMPORTANT */
}

.ep-ta4-divider{
  width:1px;
  height:56px;
  background: linear-gradient(to bottom, transparent, rgba(255,255,255,.35), transparent);
}

.ep-ta4-logo{
  height:70px !important; /* IMPORTANT */
  width:auto !important;
  max-width:100% !important;
  object-fit:contain;
  display:block;
}

/* Text */
.ep-ta4-text{ min-width:0; color:var(--text); }
.ep-ta4-title{
  font-size:22px;
  font-weight:800;
  line-height:1.15;
  margin:0;
}
.ep-ta4-desc{
  margin-top:8px;
  font-size:14px;
  line-height:1.45;
  color:var(--muted);
  max-width:70ch;
}
.ep-ta4-meta{
  margin-top:12px;
  display:flex;
  flex-wrap:wrap;
  gap:8px;
}
.ep-ta4-pill{
  display:inline-flex;
  align-items:center;
  padding:7px 12px;
  border-radius:999px;
  background: var(--pill);
  border:1px solid rgba(255,255,255,.10);
  font-size:12px;
  color: rgba(255,255,255,.84);
  white-space:nowrap;
}
.ep-ta4-stars{
  color: var(--green2);
  font-weight:900;
  letter-spacing:1px;
}

/* CTA */
.ep-ta4-cta{
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:10px;
}
.ep-ta4-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:14px 22px;
  border-radius:16px;
  background: linear-gradient(135deg,var(--green),var(--green2));
  color:#fff !important;
  text-decoration:none !important;
  font-weight:900;
  font-size:15px;
  border:1px solid rgba(255,255,255,.16);
  box-shadow: 0 14px 28px rgba(0,0,0,.22);
  transition: transform .18s ease, box-shadow .18s ease;
  white-space:nowrap;
}
.ep-ta4-btn:hover{ transform: translateY(-2px); box-shadow: 0 18px 34px rgba(0,0,0,.28); }
.ep-ta4-mini{
  font-size:12px;
  color: rgba(255,255,255,.62);
  text-align:right;
  max-width:240px;
}

/* ===== Tablet (FIXED): no overlap, better balance ===== */
@media (max-width:1024px){
  .ep-ta4-inner{
    grid-template-columns: 1fr;
    gap:14px;
    min-height:0;
  }

  .ep-ta4-logos{
    max-width:none;
    grid-template-columns: 1fr 1px 150px; /* keep TA controlled */
  }

  /* Slightly smaller logos on tablet to keep spacing perfect */
  .ep-ta4-logo{ height:60px !important; }

  .ep-ta4-cta{
    flex-direction:row;
    align-items:center;
    justify-content:space-between;
  }
  .ep-ta4-mini{ text-align:left; max-width:none; }
}

/* ===== Mobile ===== */
@media (max-width:767px){
  .ep-ta4-inner{ padding:14px; }

  .ep-ta4-logos{
    grid-template-columns: 1fr 1px 120px;
    padding:12px;
  }
  .ep-ta4-logo{ height:52px !important; }
  .ep-ta4-divider{ height:42px; }

  .ep-ta4-title{ font-size:18px; }

  .ep-ta4-cta{
    flex-direction:column;
    align-items:stretch;
    gap:8px;
  }
  .ep-ta4-btn{ width:100%; }
  .ep-ta4-mini{ text-align:center; }
}

/* Very small phones */
@media (max-width:380px){
  .ep-ta4-logos{ grid-template-columns: 1fr 1px 105px; }
  .ep-ta4-logo{ height:46px !important; }
}
</style>				</div>
				</div>
					</div>
				</div>
